const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>'₹'+n.toLocaleString('en-IN');
const devices=[
{id:1,name:'Multiparameter patient monitor',category:'Patient monitoring',condition:'Refurbished',city:'Bengaluru',price:38000,img:'monitor',year:2020,description:'A sample refurbished monitor listing with ECG, SpO₂ and respiration display. Actual specifications, test reports and accessories must be verified for each unit.'},
{id:2,name:'Ultrasound diagnostic cart',category:'Diagnostic imaging',condition:'For refurbishment',city:'Chennai',price:92000,img:'ultrasound',year:2018,description:'A sample acquisition opportunity for a retired ultrasound cart. Probe condition, imaging performance and repair scope require inspection.'},
{id:3,name:'Patient monitor components',category:'Patient monitoring',condition:'Parts recovery',city:'Hyderabad',price:8500,img:'exploded',year:2017,description:'A sample parts-recovery unit. Compatibility and recoverability are subject to inspection. The exploded image is illustrative, not a manufacturer service diagram.'},
{id:4,name:'Bedside monitoring unit',category:'Patient monitoring',condition:'For refurbishment',city:'Mumbai',price:16000,img:'monitor',year:2019,description:'A sample retired bedside monitor with intermittent display issues. Assessment is required to establish a repair plan and final acquisition value.'},
{id:5,name:'Refurbished ultrasound system',category:'Diagnostic imaging',condition:'Refurbished',city:'Pune',price:185000,img:'ultrasound',year:2021,description:'A sample refurbished diagnostic system listing. Intended to demonstrate how specifications, accessories and inspection documentation could be presented.'},
{id:6,name:'Monitor parts & assemblies',category:'Patient monitoring',condition:'Parts recovery',city:'Kochi',price:6500,img:'exploded',year:2016,description:'A sample equipment-recovery lot. No components are represented as tested or fit for clinical use. Images show a generic conceptual assembly.'}
];
const saved=new Set();let savedOnly=false,toastTimer;
const assessments=[{id:'MC-2408',device:'Bedside patient monitor',model:'Sample monitor · 2 units',city:'Bengaluru',status:'Inspection pending',note:'Sample assessment · Awaiting bench inspection',offer:null},{id:'MC-2407',device:'Ultrasound diagnostic cart',model:'Sample imaging system · 1 unit',city:'Chennai',status:'Offer ready',note:'Sample offer · Subject to agreed transfer conditions',offer:48000},{id:'MC-2406',device:'Patient monitoring equipment',model:'Sample recovery lot · 4 units',city:'Hyderabad',status:'Collection scheduled',note:'Sample collection · 22 September, 10:00–13:00',offer:null}];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600)}
function view(v){if(!['market','sell','pipeline'].includes(v))throw Error('Unknown view');$$('.view').forEach(e=>e.hidden=e.id!==v+'-view');$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(v==='pipeline')renderPipeline();window.scrollTo({top:0,behavior:'instant'});return v}
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-goto]').forEach(b=>b.onclick=()=>view(b.dataset.goto));$$('.brand').forEach(a=>a.onclick=e=>{e.preventDefault();view('market')});
function render(){let list=devices.filter(d=>(!savedOnly||saved.has(d.id))&&($('#category').value==='all'||d.category===$('#category').value)&&($('#condition').value==='all'||d.condition===$('#condition').value)&&(d.name+' '+d.category+' '+d.city).toLowerCase().includes($('#search').value.trim().toLowerCase()));if($('#sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')list.sort((a,b)=>b.price-a.price);$('#cards').innerHTML=list.map(d=>`<article class="device-card"><div class="card-art"><span class="badge ${d.condition==='Refurbished'?'refurb':''}">${d.condition}</span><button class="save ${saved.has(d.id)?'on':''}" data-save="${d.id}" aria-label="${saved.has(d.id)?'Unsave':'Save'} ${d.name}" aria-pressed="${saved.has(d.id)}">${saved.has(d.id)?'♥':'♡'}</button><img src="assets/${d.img}.png" alt="Illustrative 3D render for ${d.name}" loading="lazy"></div><div class="card-info"><span class="card-meta">${d.category}</span><h3>${d.name}</h3><p class="location">⌖ ${d.city} <span>· ${d.year}</span></p><div class="card-price"><strong>${money(d.price)}</strong><button data-detail="${d.id}">View details ↗</button></div></div></article>`).join('');$('#count').textContent=list.length;$('#saved-count').textContent=saved.size;$('#empty').hidden=list.length>0;$$('[data-save]').forEach(b=>b.onclick=()=>{const id=+b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);render()});$$('[data-detail]').forEach(b=>b.onclick=()=>detail(+b.dataset.detail));return list.map(({id,name,price,condition})=>({id,name,price,condition}))}
['search','category','condition','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));
function stock(s){savedOnly=s;$('#all-stock').classList.toggle('selected',!s);$('#saved-stock').classList.toggle('selected',s);render()}
$('#all-stock').onclick=()=>stock(false);$('#saved-stock').onclick=()=>stock(true);$('#reset-filters').onclick=()=>{$('#search').value='';$('#category').value=$('#condition').value='all';stock(false)};
function info(title,body){$('#info-content').innerHTML=`<p class="eyebrow">MEDICYCLE</p><h2>${esc(title)}</h2>${body}`;$('#info-dialog').showModal()}
$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function detail(id){const d=devices.find(d=>d.id===id);if(!d)throw Error('Unknown device');$('#detail-content').innerHTML=`<p class="eyebrow">SAMPLE EQUIPMENT · MC-${String(id).padStart(4,'0')}</p><div class="detail-grid"><div><img src="assets/${d.img}.png" alt="Illustrative ${d.name}"><p>Generic 3D concept render. Actual unit photos and documentation would accompany a live listing.</p></div><div><span class="status">${d.condition}</span><h2>${d.name}</h2><p>${d.description}</p><div class="detail-price">${money(d.price)} <span style="font:12px 'DM Sans';color:#6d7d74">indicative</span></div><div class="spec"><span>Location</span><b>${d.city}</b></div><div class="spec"><span>Year</span><b>${d.year}</b></div><div class="spec"><span>Listing type</span><b>Demonstration</b></div><div class="detail-actions"><button class="primary" id="enquire">Request information ↗</button><button class="secondary" id="report">Inspection checklist</button></div></div></div>`;$('#detail-dialog').showModal();$('#report').onclick=()=>info('Inspection checklist','<p>A live report would document these checks for this particular unit:</p><ul><li>Identity, ownership and service history</li><li>Visual condition and included accessories</li><li>Electrical safety and functional testing</li><li>Faults, replacement parts and final disposition</li></ul><p>No inspection report has been issued for this sample listing.</p>');$('#enquire').onclick=()=>{info('Request equipment information',`<p>Ask about ${esc(d.name)}. This is a demo enquiry, not a message to a seller.</p><form id="enquiry-form"><label>Your email<input type="email" required placeholder="you@hospital.com"></label><label style="margin-top:15px">Your question<textarea required rows="3" placeholder="Availability, accessories or condition?"></textarea></label><button class="primary" style="margin-top:20px">Save demo enquiry</button></form>`);$('#enquiry-form').onsubmit=e=>{e.preventDefault();$('#info-dialog').close();toast('Demo enquiry recorded for this session. No message was sent.')}};return {id:d.id,name:d.name}}
function setDeviceView(exploded){$('#hero-image').src=exploded?'assets/exploded.png':'assets/monitor.png';$('#hero-image').alt=exploded?'Illustrative exploded view showing monitor housing, display and internal electronics':'Three-dimensional rendering of a generic patient monitor';$('#device-stage').classList.toggle('exploded',exploded);$('#assembled').classList.toggle('selected',!exploded);$('#exploded').classList.toggle('selected',exploded);$('#assembled').setAttribute('aria-pressed',String(!exploded));$('#exploded').setAttribute('aria-pressed',String(exploded));return exploded?'exploded':'assembled'}
$('#assembled').onclick=()=>setDeviceView(false);$('#exploded').onclick=()=>setDeviceView(true);
const parts={'Display assembly':'The screen and front interface present measurements and equipment status. During assessment, the team would review display integrity, controls and connectors.','Signal processing board':'Internal electronics process sensor inputs. Board condition, corrosion, connectors and repairability would be assessed against the specific device documentation.','Power module':'The power assembly supplies the device electronics. Its condition and safety require assessment by a qualified biomedical service team.'};$$('[data-part]').forEach(b=>b.onclick=()=>info(b.dataset.part,`<img src="assets/exploded.png" alt="Conceptual exploded monitor assembly" style="width:100%;max-height:280px;object-fit:contain"><p>${parts[b.dataset.part]}</p><p style="font-size:12px">Conceptual component guide. Not a manufacturer-specific service or disassembly instruction.</p>`));
let photoURLs=[];$('#photos').onchange=e=>{photoURLs.forEach(URL.revokeObjectURL);photoURLs=[];$('#photo-previews').replaceChildren();const files=[...e.target.files];if(files.length>5||files.some(f=>f.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){e.target.value='';toast('Choose up to 5 JPG, PNG or WebP images, each under 10 MB.');return}for(const f of files){const img=document.createElement('img');img.alt='Preview of '+f.name;img.src=URL.createObjectURL(f);photoURLs.push(img.src);$('#photo-previews').append(img)}};
$('#sell-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const a={id:'MC-'+(2409+assessments.length-3),device:f.get('device').trim(),model:f.get('model').trim()+' · '+f.get('quantity')+' unit(s)',city:f.get('city').trim(),status:'Submitted',note:'Demo intake saved in this tab · '+f.get('condition'),offer:null};if(!a.device||!a.city){toast('Please enter a device name and city.');return}assessments.unshift(a);e.target.reset();photoURLs.forEach(URL.revokeObjectURL);photoURLs=[];$('#photo-previews').replaceChildren();view('pipeline');toast('Demo assessment '+a.id+' added. No data was sent to a business.');};
function renderPipeline(){$('#open-count').textContent=assessments.length;$('#pipeline-list').innerHTML=assessments.map(a=>`<div class="pipeline-row"><div><h3>${esc(a.device)}</h3><p>${esc(a.id)} · ${esc(a.model)}</p></div><p>⌖ ${esc(a.city)}</p><span class="status">${esc(a.status)}</span><button data-assessment="${a.id}">View →</button></div>`).join('');$$('[data-assessment]').forEach(b=>b.onclick=()=>{const a=assessments.find(x=>x.id===b.dataset.assessment);info(a.device,`<p>${esc(a.id)} · ${esc(a.model)} · ${esc(a.city)}</p><span class="status">${esc(a.status)}</span><p>${esc(a.note)}</p>${a.offer?'<div class="detail-price">'+money(a.offer)+'</div><button class="primary" id="accept-offer">Accept demo offer</button>':''}<p>This is a demonstration workflow. No pickup, purchase or payment is arranged.</p>`);if(a.offer)$('#accept-offer').onclick=()=>{a.status='Offer accepted';a.note='Demo offer accepted · Collection details still to be agreed';a.offer=null;$('#info-dialog').close();renderPipeline();toast('Demo offer accepted. No transaction was made.')}})}
$('#account').onclick=()=>info('Demo workspace','<p>You are exploring a sample acquisition account. Sign-in, shared records, payments and live messaging are not connected.</p><p>Saved equipment and submitted assessments reset when this page is reloaded.</p>');$('#about').onclick=()=>info('A second life for medical equipment','<p>Medicycle is a marketplace concept for acquiring retired equipment, assessing refurbishment potential and recovering usable parts.</p><p>This working front-end prototype includes sample inventory, session-only assessments, offers, photo previews and illustrative 3D device views. It does not arrange real transactions or certify device safety.</p>');
render();renderPipeline();setDeviceView(false);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'search_demo_equipment',title:'Search demo equipment',description:'Filter the visible sample equipment inventory. Does not query live stock.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},execute:input=>{if(!input||typeof input.query!=='string'||input.query.length>200)throw Error('query must be a string of at most 200 characters');view('market');stock(false);$('#search').value=input.query;$('#category').value=$('#condition').value='all';return{equipment:render()}}},{name:'start_demo_equipment_assessment',title:'Open equipment assessment',description:'Open the demo seller form. Does not submit or create an assessment.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:input=>{if(!input||Object.keys(input).length)throw Error('No arguments expected');return{view:view('sell'),submitted:false}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
